<script>
  // Simple period filter toggle micro-interaction
  document.querySelectorAll('.period-pill').forEach(btn => {
    btn.addEventListener('click', function() {
      document.querySelectorAll('.period-pill').forEach(b => {
        b.classList.remove('bg-primary', 'text-white', 'font-bold', 'shadow-[0_6px_16px_-3px_rgba(65,44,231,0.45)]');
        b.classList.add('text-slate-500');
      });
      this.classList.remove('text-slate-500');
      this.classList.add('bg-primary', 'text-white', 'font-bold', 'shadow-[0_6px_16px_-3px_rgba(65,44,231,0.45)]');
    });
  });
</script>
